/** The four callouts of spec/02 §3.11, named as the CSS modifiers of sb-callout. */
enum class SbCalloutKind { Note, Warning, Error, Success }

/** [SbCallout] for a text without a file name. */
@Composable
fun SbCallout(
    kind: SbCalloutKind,
    text: String,
    modifier: Modifier = Modifier,
    title: String? = null,
    inlineTitle: Boolean = false,
    live: Boolean = false,
    onHide: (() -> Unit)? = null,
    actions: (@Composable RowScope.() -> Unit)? = null,
) {
    SbCallout(kind, AnnotatedString(text), modifier, title, inlineTitle, live, onHide, actions)
}

/**
 * Callout (spec/02 §3.11): the 20 dp filled glyph of [kind] in its status colour, then [title] (null = the kind's word:
 * „Hinweis“, „Achtung“, „Fehler“, „Erfolg“) in bodyStrong over [text] in body, both in text, inside a 1 dp border
 * hairline frame, radius container, 12 by 16 dp inside. No fill and no coloured edge (the 3 dp edge means place). A
 * file name in [text] marked with sbFileName breaks only after - . _ / without a hyphen (D101 (6)); only an ordinary
 * word wider than the line is hyphenated (D99 (1)); the marked name never counts as such a word. Provisional (agent):
 * an unmarked name or code wider than the line is hyphenated like a word (Compose has no code mark, D101 (10)).
 * One TalkBack node for glyph, title and text; actions and „Ausblenden“ are stops of their own.
 * [inlineTitle] (spec/02 §3.11; provisional, agent): a callout of one sentence without a title line; the sentence starts
 * with the kind's word (or [title]) and its colon in bodyStrong („Achtung: Die Datei ist kein UTF-8.“), so glyph and word
 * stay together. [live] (spec/02 §3.11; provisional, agent): the callout appears while the screen is in use; TalkBack hears it
 * at once (assertive) when it is a warning or error with [actions] (it asks for a decision), else politely; the
 * region is this node, which enters together with its text: not verified with TalkBack (spec/08 §14.18). [actions]
 * (D102 (39), spec/02 §3.11): secondary or text actions under the text, never the primary action; [onHide] adds the text
 * action „Ausblenden“ with the 16 dp close glyph after them. With the focus on one of them the whole callout scrolls into
 * view (CHECKS.md §84).
 */
@Composable
fun SbCallout(
    kind: SbCalloutKind,
    text: AnnotatedString,
    modifier: Modifier = Modifier,
    title: String? = null,
    inlineTitle: Boolean = false,
    live: Boolean = false,
    onHide: (() -> Unit)? = null,
    actions: (@Composable RowScope.() -> Unit)? = null,
) {
    val c = SebaroTheme.colors
    val t = SebaroTheme.tokens
    val ty = SebaroTheme.typography
    val m = sbMessages()
    val (icon, tint, word) = when (kind) {
        SbCalloutKind.Note -> Triple(SebaroIcons.Filled.Info, c.info, m.calloutNote)
        SbCalloutKind.Warning -> Triple(SebaroIcons.Filled.Warning, c.warning, m.calloutWarning)
        SbCalloutKind.Error -> Triple(SebaroIcons.Filled.Error, c.danger, m.calloutError)
        SbCalloutKind.Success -> Triple(SebaroIcons.Filled.Success, c.success, m.calloutSuccess)
    }
    val density = LocalDensity.current
    // centred on the title's first line at every text size (2 dp at font scale 1, the web's margin-block-start)
    val lift = with(density) { (ty.bodyStrong.lineHeight.toDp() - t.size.iconMd) / 2 }
    val decides = actions != null && (kind == SbCalloutKind.Warning || kind == SbCalloutKind.Error)
    Row(
        modifier
            .then(if (actions != null || onHide != null) Modifier.sbShowWholeOnFocus() else Modifier)
            .fillMaxWidth()
            .border(t.borderWidth.hairline, c.border, t.shapes.container)
            .padding(horizontal = t.space.s4, vertical = t.space.s3),
        horizontalArrangement = Arrangement.spacedBy(t.space.s3),
    ) {
        Icon(icon, contentDescription = null, tint = tint, modifier = Modifier.padding(top = lift).size(t.size.iconMd))
        Column(Modifier.weight(1f), verticalArrangement = Arrangement.spacedBy(t.space.s3)) {
            Column(
                Modifier.semantics(mergeDescendants = true) {
                    if (live) liveRegion = if (decides) LiveRegionMode.Assertive else LiveRegionMode.Polite
                },
            ) {
                if (inlineTitle) {
                    val sentence = buildAnnotatedString {
                        // the colon in the bold word, as the web's <strong class="sb-callout__kind">Achtung:</strong>
                        withStyle(SpanStyle(fontWeight = ty.bodyStrong.fontWeight)) { append(title ?: word); append(":") }
                        append(" ")
                        append(text)
                    }
                    SbWrapText(sentence, ty.body, c.text)
                } else {
                    SbWrapText(title ?: word, ty.bodyStrong, c.text)
                    SbWrapText(text, ty.body, c.text)
                }
            }
            if (actions != null || onHide != null) {
                // the actions wrap under each other when they do not fit side by side (large text); „Ausblenden“ last
                SbFlowRow(horizontalArrangement = Arrangement.spacedBy(t.space.s3), verticalArrangement = Arrangement.spacedBy(t.space.s2)) {
                    actions?.invoke(this)
                    if (onHide != null) SbTextAction(m.calloutHide, onHide, icon = SebaroIcons.Outline16.Close)
                }
            }
        }
    }
}
